// Your new Node.js app. FloServer runs `npm start` and passes the port in PORT.
const http = require('node:http');

const port = Number(process.env.PORT) || 3000;

http.createServer((req, res) => {
  res.writeHead(200, { 'Content-Type': 'text/html; charset=utf-8' });
  res.end(`<!doctype html><title>Node app</title>
<body style="font-family: system-ui, sans-serif; margin: 3rem">
<h1>Node app</h1><p>Running on Node.js ${process.version}. Edit <code>server.js</code> to start.</p>`);
}).listen(port, '127.0.0.1');

{
    "name": "app/mcp-server",
    "description": "An MCP server made with FloServer",
    "type": "project",
    "license": "proprietary",
    "require": {
        "php": ">=8.2",
        "mcp/sdk": "^0.9",
        "nyholm/psr7": "^1.8",
        "laminas/laminas-httphandlerrunner": "^2.10"
    },
    "autoload": {
        "psr-4": {
            "App\\": "src/"
        }
    },
    "config": {
        "allow-plugins": {
            "php-http/discovery": false
        }
    }
}
